const markUnprocessable = `-- name: MarkUnprocessable :exec
UPDATE notifications
SET status = 'failed', failure_reason = 'unprocessable_message', failed_at = now(), updated_at = now()
WHERE id = $1 AND status = 'queued'
`

// Fails a queued notification whose message cannot be processed (ADR 0014).
func (q *Queries) MarkUnprocessable(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, markUnprocessable, id)
	return err
}

const queueDueNotifications = `-- name: QueueDueNotifications :execrows
WITH due AS (
    SELECT d.id FROM notifications d
    WHERE d.status IN ('scheduled', 'retrying') AND d.next_attempt_at <= now()
    ORDER BY d.next_attempt_at
    LIMIT $1::integer
    FOR UPDATE SKIP LOCKED
), queued AS (
    UPDATE notifications n SET status = 'queued', next_attempt_at = NULL, updated_at = now()
    FROM due WHERE n.id = due.id
    RETURNING n.id
)
INSERT INTO outbox (notification_id) SELECT id FROM queued
`

// Queues up to batch_size waiting notifications whose time has come, soonest first, with their outbox rows, in one
// statement. SKIP LOCKED keeps two schedulers from queueing one notification twice.
func (q *Queries) QueueDueNotifications(ctx context.Context, batchSize int) (int64, error) {
	result, err := q.db.Exec(ctx, queueDueNotifications, batchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const reapExpiredClaims = `-- name: ReapExpiredClaims :execrows
WITH expired AS (
    SELECT e.id, e.attempts FROM notifications e
    WHERE e.status = 'sending' AND e.claimed_until < now()
    ORDER BY e.claimed_until
    LIMIT $2::integer
    FOR UPDATE SKIP LOCKED
), recorded AS (
    INSERT INTO delivery_attempts (notification_id, attempt, outcome, error, duration_ms)
    SELECT expired.id, expired.attempts, 'unknown', 'the worker that claimed it stopped before recording an outcome', 0
    FROM expired
)
UPDATE notifications n
SET status = CASE WHEN expired.attempts >= $1::integer THEN 'failed' ELSE 'retrying' END,
    claimed_until = NULL,
    next_attempt_at = CASE WHEN expired.attempts >= $1::integer THEN NULL ELSE now() END,
    failure_reason = CASE WHEN expired.attempts >= $1::integer THEN 'attempts_exhausted' END,
    failed_at = CASE WHEN expired.attempts >= $1::integer THEN now() END,
    updated_at = now()
FROM expired
WHERE n.id = expired.id
`

type ReapExpiredClaimsParams struct {
	MaxAttempts int
	BatchSize   int
}

// Returns notifications whose worker's lease ran out to retrying, due at once, or to failed when no attempt is
// left, recording the attempt the lost worker made as unknown (ADR 0012).
func (q *Queries) ReapExpiredClaims(ctx context.Context, arg ReapExpiredClaimsParams) (int64, error) {
	result, err := q.db.Exec(ctx, reapExpiredClaims, arg.MaxAttempts, arg.BatchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const releaseClaim = `-- name: ReleaseClaim :exec
UPDATE notifications
SET status = 'queued', claimed_until = NULL, attempts = attempts - 1, updated_at = now()
WHERE id = $1 AND status = 'sending' AND attempts = $2
`

type ReleaseClaimParams struct {
	ID      uuid.UUID
	Attempt int
}

// Undoes a claim whose send never started, giving back its attempt, if the claim is still the one that took it.
func (q *Queries) ReleaseClaim(ctx context.Context, arg ReleaseClaimParams) error {
	_, err := q.db.Exec(ctx, releaseClaim, arg.ID, arg.Attempt)
	return err
}

const requeueFailedNotification = `-- name: RequeueFailedNotification :one
UPDATE notifications
SET status = 'queued', failed_at = NULL, failure_reason = NULL, attempts = 0, updated_at = now()
WHERE id = $1 AND status = 'failed'
RETURNING id, channel, recipient, content, priority, status, idempotency_key, request_hash, correlation_id, created_at, updated_at, batch_id, batch_index, failed_at, next_attempt_at, attempts, claimed_until, failure_reason, provider_message_id, scheduled_at, template_id, trace_parent
`

// Puts a failed notification back in the queue; returns no row when it is not failed.
func (q *Queries) RequeueFailedNotification(ctx context.Context, id uuid.UUID) (Notification, error) {
	row := q.db.QueryRow(ctx, requeueFailedNotification, id)
	var i Notification
	err := row.Scan(
		&i.ID,
		&i.Channel,
		&i.Recipient,
		&i.Content,
		&i.Priority,
		&i.Status,
		&i.IdempotencyKey,
		&i.RequestHash,
		&i.CorrelationID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.BatchID,
		&i.BatchIndex,
		&i.FailedAt,
		&i.NextAttemptAt,
		&i.Attempts,
		&i.ClaimedUntil,
		&i.FailureReason,
		&i.ProviderMessageID,
		&i.ScheduledAt,
		&i.TemplateID,
		&i.TraceParent,
	)
	return i, err
}

const requeueFailedNotifications = `-- name: RequeueFailedNotifications :execrows
WITH picked AS (
    SELECT f.id FROM notifications f
    WHERE f.status = 'failed' AND f.failed_at >= $1::timestamptz
      AND f.failed_at < $2::timestamptz
      AND ($3::text IS NULL OR f.channel = $3::text)
      AND ($4::uuid IS NULL OR f.batch_id = $4::uuid)
    ORDER BY f.failed_at, f.id
    LIMIT $5::integer
    FOR UPDATE SKIP LOCKED
), requeued AS (
    UPDATE notifications n
    SET status = 'queued', failed_at = NULL, failure_reason = NULL, attempts = 0, updated_at = now()
    FROM picked WHERE n.id = picked.id
    RETURNING n.id
)
INSERT INTO outbox (notification_id) SELECT id FROM requeued
`

type RequeueFailedNotificationsParams struct {
	FailedFrom time.Time
	FailedTo   time.Time
	Channel    *string
	BatchID    *uuid.UUID
	MaxRows    int
}

// Puts up to max_rows failed notifications, oldest failure first, back in the queue with their outbox rows, in one
// statement. SKIP LOCKED keeps two bulk retries from requeueing one notification twice.
func (q *Queries) RequeueFailedNotifications(ctx context.Context, arg RequeueFailedNotificationsParams) (int64, error) {
	result, err := q.db.Exec(ctx, requeueFailedNotifications,
		arg.FailedFrom,
		arg.FailedTo,
		arg.Channel,
		arg.BatchID,
		arg.MaxRows,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

